type KnowledgeStatus = "draft" | "review" | "approved" | "published" | "inactive";
type ContentNoticeKind = "new" | "updated";
type Course = { id: string; title: string; track: string };
type Discipline = { id: number; name: string; shortName: string; description: string | null; status: KnowledgeStatus; requiresReview: boolean; courseIds: string[]; contentIds: number[] };
type Content = { id: number; title: string; objective: string | null; description: string | null; cardText: string | null; body: string | null; coverImageUrl: string | null; videoUrl: string | null; videoLabel: string | null; materialUrl: string | null; materialLabel: string | null; noticeKind: ContentNoticeKind | null; status: KnowledgeStatus; requiresReview: boolean; disciplineIds: number[] };
type Question = { id: number; statement: string; questionType: "certo_errado" | "multipla_escolha"; options: string[]; answer: boolean | string; explanation: string | null; difficulty: "basic" | "intermediate" | "advanced"; source: string | null; banca: string | null; year: number | null; status: KnowledgeStatus; requiresReview: boolean; contentIds: number[]; contents: { id: number; title: string; status: KnowledgeStatus }[] };
type ReviewItem = { id: number; itemType: "question" | "content"; itemId: number; status: "pending" | "approved" | "rejected" | "correction_requested"; title: string; itemStatus: KnowledgeStatus; notes: string | null; createdAt: Date };

const statusLabels: Record<KnowledgeStatus, string> = { draft: "RASCUNHO", review: "EM REVISÃO", approved: "APROVADO", published: "PUBLICADO", inactive: "INATIVO" };
const statusClasses: Record<KnowledgeStatus, string> = { draft: "border-[#c9c8c0] bg-[#f5f4ef] text-[#666962]", review: "border-[#d7bb7f] bg-[#fff7e5] text-[#8d611a]", approved: "border-[#9bcfc0] bg-[#ecf8f3] text-[#176a5a]", published: "border-[#8fc2d0] bg-[#eaf7fb] text-[#0a5b73]", inactive: "border-[#d8afa2] bg-[#fff0ec] text-[#98462f]" };
const reviewLabels: Record<ReviewItem["status"], string> = { pending: "PENDENTE", approved: "APROVADA", rejected: "REJEITADA", correction_requested: "CORREÇÃO SOLICITADA" };

function toggleId<T extends string | number>(items: T[], value: T) {
  return items.includes(value) ? items.filter(item => item !== value) : [...items, value];
}

function StatusBadge({ status }: { status: KnowledgeStatus }) {
  return <span className={`inline-flex border px-2 py-1 text-[9px] font-bold tracking-wider ${statusClasses[status]}`}>{statusLabels[status]}</span>;
}

function readContentImageAsBase64(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Não foi possível ler a imagem selecionada."));
    reader.onload = () => {
      const encoded = typeof reader.result === "string" ? reader.result.split(",")[1] : "";
      if (!encoded) reject(new Error("A imagem selecionada não possui dados válidos."));
      else resolve(encoded);
    };
    reader.readAsDataURL(file);
  });
}

function ToggleList<T extends string | number>({ values, options, onChange, empty }: { values: T[]; options: { id: T; label: string; caption?: string }[]; onChange: (values: T[]) => void; empty: string }) {
  if (!options.length) return <p className="border border-dashed border-[#c7beb0] p-3 text-[11px] leading-5 text-[#718084]">{empty}</p>;
  return <div className="max-h-36 space-y-1 overflow-y-auto border border-[#d7d0c4] bg-white p-2">{options.map(option => <label key={option.id} className="flex cursor-pointer items-start gap-2 rounded px-1 py-1 text-[11px] hover:bg-[#f2f7f5]"><input type="checkbox" checked={values.includes(option.id)} onChange={() => onChange(toggleId(values, option.id))} className="mt-0.5 accent-[#0e5a70]"/><span><b className="text-[#1e4650]">{option.label}</b>{option.caption && <small className="ml-1 text-[#748588]">{option.caption}</small>}</span></label>)}</div>;
}

function ContentNoticeControl({ value, onChange }: { value: ContentNoticeKind | null; onChange: (value: ContentNoticeKind | null) => void }) {
  return <fieldset className="border border-[#e4cfab] bg-[#fffaf0] p-3"><legend className="px-1 text-[11px] font-bold text-[#7a5521]">Aviso para alunos que já tinham o curso</legend><div className="mt-1 grid gap-2 sm:grid-cols-3"><label className="flex cursor-pointer items-center gap-2 border border-[#e8dfd0] bg-white p-2 text-[11px] font-bold text-[#53656a]"><input type="radio" name="contentNoticeKind" checked={value === null} onChange={() => onChange(null)} className="accent-[#0e5a70]"/>Sem aviso</label><label className="flex cursor-pointer items-center gap-2 border border-[#90cdbb] bg-[#f2fbf7] p-2 text-[11px] font-bold text-[#176a5a]"><input type="radio" name="contentNoticeKind" checked={value === "new"} onChange={() => onChange("new")} className="accent-[#176a5a]"/>Conteúdo novo</label><label className="flex cursor-pointer items-center gap-2 border border-[#e9bc75] bg-[#fff6e8] p-2 text-[11px] font-bold text-[#895a22]"><input type="radio" name="contentNoticeKind" checked={value === "updated"} onChange={() => onChange("updated")} className="accent-[#a36b23]"/>Conteúdo atualizado</label></div><p className="mt-2 text-[10px] leading-4 text-[#786544]">Somente alunos com matrícula iniciada antes deste salvamento verão o aviso. Ele some para cada aluno quando abrir a aula; compras posteriores não recebem o rótulo.</p></fieldset>;
}

export function KnowledgeBaseManager({ courses }: { courses: Course[] }) {
  const [activeTab, setActiveTab] = useState<"questions" | "byContent" | "contents" | "disciplines" | "import" | "review">("questions");
  const [message, setMessage] = useState<string | null>(null);
  const [questionSearch, setQuestionSearch] = useState("");
  const [questionStatus, setQuestionStatus] = useState<KnowledgeStatus | "all">("all");
  const [reviewType, setReviewType] = useState<"all" | "question" | "content">("all");
  const [reviewStatus, setReviewStatus] = useState<"all" | ReviewItem["status"]>("pending");
  const [reviewSearch, setReviewSearch] = useState("");
  const [questionToEditId, setQuestionToEditId] = useState<number | null>(null);
  const disciplinesQuery = trpc.admin.disciplines.list.useQuery();
  const contentsQuery = trpc.admin.contents.list.useQuery();
  const questionQueryInput = useMemo(() => ({ search: questionSearch || undefined, status: questionStatus === "all" ? undefined : questionStatus }), [questionSearch, questionStatus]);
  const questionsQuery = trpc.admin.questions.list.useQuery(questionQueryInput);
  const allQuestionsQueryInput = useMemo(() => ({}), []);
  const allQuestionsQuery = trpc.admin.questions.list.useQuery(allQuestionsQueryInput);
  const reviewQueryInput = useMemo(() => ({ itemType: reviewType === "all" ? undefined : reviewType, status: reviewStatus === "all" ? undefined : reviewStatus, search: reviewSearch || undefined }), [reviewType, reviewStatus, reviewSearch]);
  const reviewQuery = trpc.admin.review.list.useQuery(reviewQueryInput);
  const pendingQuery = trpc.admin.review.pendingCount.useQuery();
  const utils = trpc.useUtils();
  const refresh = async () => {
    await Promise.all([utils.admin.disciplines.invalidate(), utils.admin.contents.invalidate(), utils.admin.questions.invalidate(), utils.admin.review.invalidate(), utils.admin.auditLogs.invalidate()]);
  };
  const complete = (text: string) => async () => { setMessage(text); await refresh(); };
  const fail = (error: { message: string }) => setMessage(error.message);
  const disciplineCreate = trpc.admin.disciplines.create.useMutation({ onSuccess: complete("Disciplina criada com seus vínculos reutilizáveis."), onError: fail });
  const disciplineUpdate = trpc.admin.disciplines.update.useMutation({ onSuccess: complete("Disciplina atualizada."), onError: fail });
  const contentCreate = trpc.admin.contents.create.useMutation({ onSuccess: complete("Conteúdo criado e auditado."), onError: fail });
  const contentUpdate = trpc.admin.contents.update.useMutation({ onSuccess: complete("Conteúdo atualizado sem perder histórico."), onError: fail });
  const contentImageUpload = trpc.admin.contents.uploadImage.useMutation({ onError: fail });
  const questionCreate = trpc.admin.questions.create.useMutation({ onSuccess: created => complete(questionCreationSuccessMessage(created.id))(), onError: fail });
  const questionUpdate = trpc.admin.questions.update.useMutation({ onSuccess: complete("Questão atualizada; o histórico anterior foi preservado."), onError: fail });
  const questionDelete = trpc.admin.questions.remove.useMutation({ onSuccess: complete("Questão excluída antes de qualquer uso em simulado."), onError: fail });
  const sendContent = trpc.admin.contents.sendToReview.useMutation({ onSuccess: complete("Conteúdo enviado para revisão."), onError: fail });
  const sendQuestion = trpc.admin.questions.sendToReview.useMutation({ onSuccess: complete("Questão enviada para revisão."), onError: fail });
  const decideReview = trpc.admin.review.decide.useMutation({ onSuccess: complete("Decisão de revisão registrada."), onError: fail });
  const pending = disciplineCreate.isPending || disciplineUpdate.isPending || contentCreate.isPending || contentUpdate.isPending || contentImageUpload.isPending || questionCreate.isPending || questionUpdate.isPending || questionDelete.isPending || sendContent.isPending || sendQuestion.isPending || decideReview.isPending;
  const disciplines = (disciplinesQuery.data ?? []) as Discipline[];
  const contents = (contentsQuery.data ?? []) as Content[];
  const questions = (questionsQuery.data ?? []) as Question[];
  const allQuestions = (allQuestionsQuery.data ?? []) as Question[];
  const reviews = (reviewQuery.data ?? []) as ReviewItem[];

  return <section className="mt-7 border border-[#bcd8d0] bg-[#f5fbf8] p-4 sm:p-5"><div className="flex flex-col gap-3 border-b border-[#c6ded7] pb-4 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex items-center gap-2"><Layers3 className="h-5 w-5 text-[#0e5a70]"/><p className="eyebrow text-[#176a5a]">BIBLIOTECA CENTRAL</p></div><h3 className="font-display mt-1 text-lg font-bold text-[#173d4a]">Disciplinas, conteúdos, questões e revisão</h3><p className="mt-1 max-w-3xl text-xs leading-5 text-[#567471]">Os cursos fazem vínculos reutilizáveis. Uma questão possui um único identificador, mesmo quando estiver associada a vários conteúdos.</p></div><button onClick={() => setActiveTab("review")} className="inline-flex items-center justify-center gap-2 border border-[#cfb478] bg-[#fff9e9] px-3 py-2 text-xs font-bold text-[#815719]"><ClipboardCheck className="h-4 w-4"/>Revisar (ROOT) <span className="rounded-full bg-[#815719] px-1.5 py-0.5 text-[10px] text-white">{pendingQuery.data ?? 0}</span></button></div><div className="mt-4 flex flex-wrap gap-2">{([{ id: "questions", label: "Todas as questões", icon: ListChecks }, { id: "byContent", label: "Questões por conteúdo", icon: Layers3 }, { id: "contents", label: "Conteúdos", icon: BookOpenCheck }, { id: "disciplines", label: "Disciplinas", icon: Layers3 }, { id: "import", label: "Importar Excel / PDF", icon: FilePenLine }, { id: "review", label: "Revisar (ROOT)", icon: ClipboardCheck }] as const).map(tab => <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`inline-flex items-center gap-2 border px-3 py-2 text-xs font-bold ${activeTab === tab.id ? "border-[#0e5a70] bg-[#0e5a70] text-white" : "border-[#b8d3cc] bg-white text-[#24525a]"}`}><tab.icon className="h-3.5 w-3.5"/>{tab.label}{tab.id === "review" && (pendingQuery.data ?? 0) > 0 && <span className={`rounded-full px-1.5 py-0.5 text-[9px] ${activeTab === tab.id ? "bg-white text-[#0e5a70]" : "bg-[#e3ab54] text-[#593900]"}`}>{pendingQuery.data}</span>}</button>)}</div>{activeTab === "questions" && <QuestionWorkspace contents={contents} contentsLoading={contentsQuery.isLoading} questions={questions} questionsLoading={questionsQuery.isLoading} search={questionSearch} status={questionStatus} pending={pending} focusQuestionId={questionToEditId} onFocusHandled={() => setQuestionToEditId(null)} onSearch={setQuestionSearch} onStatus={setQuestionStatus} onCreate={data => questionCreate.mutateAsync(data)} onUpdate={(id, data) => questionUpdate.mutateAsync({ id, data })} onDelete={id => questionDelete.mutate({ id })} onAddToReview={id => sendQuestion.mutate({ id })}/>} {activeTab === "byContent" && <QuestionsByContent contents={contents} questions={allQuestions} loading={contentsQuery.isLoading || allQuestionsQuery.isLoading} pending={pending} onOpenQuestion={id => { setQuestionToEditId(id); setActiveTab("questions"); }}/>} {activeTab === "contents" && <ContentWorkspace disciplines={disciplines} contents={contents} contentsLoading={contentsQuery.isLoading} pending={pending} onCreate={data => contentCreate.mutate(data)} onUpdate={(id, data) => contentUpdate.mutate({ id, data })} onUploadImage={data => contentImageUpload.mutateAsync(data)} onSend={id => sendContent.mutate({ id })}/>} {activeTab === "disciplines" && <DisciplineWorkspace courses={courses} contents={contents} disciplines={disciplines} pending={pending} onCreate={data => disciplineCreate.mutate(data)} onUpdate={(id, data) => disciplineUpdate.mutate({ id, data })}/>} {activeTab === "import" && <KnowledgeBulkImportPanel disciplines={disciplines} onImported={refresh}/>} {activeTab === "review" && <ReviewWorkspace reviews={reviews} search={reviewSearch} type={reviewType} status={reviewStatus} pending={pending} onSearch={setReviewSearch} onType={setReviewType} onStatus={setReviewStatus} onOpenQuestion={id => { setQuestionToEditId(id); setActiveTab("questions"); }} onDecide={(id, decision, notes) => decideReview.mutate({ id, decision, notes })}/>} {message && <p role="status" className="mt-4 border border-[#b7d8c9] bg-white p-3 text-xs font-semibold text-[#17644e]">{message}</p>}</section>;
}

function QuestionWorkspace({ contents, contentsLoading, questions, questionsLoading, search, status, pending, focusQuestionId, onFocusHandled, onSearch, onStatus, onCreate, onUpdate, onDelete, onAddToReview }: { contents: Content[]; contentsLoading: boolean; questions: Question[]; questionsLoading: boolean; search: string; status: KnowledgeStatus | "all"; pending: boolean; focusQuestionId: number | null; onFocusHandled: () => void; onSearch: (value: string) => void; onStatus: (value: KnowledgeStatus | "all") => void; onCreate: (data: any) => Promise<unknown>; onUpdate: (id: number, data: any) => Promise<unknown>; onDelete: (id: number) => void; onAddToReview: (id: number) => void }) {
  const [editing, setEditing] = useState<Question | null>(null);
  const [newQuestionRevision, setNewQuestionRevision] = useState(0);
  const questionLoadState = libraryLoadState(questionsLoading, questions.length);
  useEffect(() => {
    if (focusQuestionId === null) return;
    const target = questions.find(question => question.id === focusQuestionId);
    if (!target) return;
    setEditing(target);
    onFocusHandled();
  }, [focusQuestionId, onFocusHandled, questions]);
  return <div className="mt-5 grid gap-5 xl:grid-cols-[1fr_1.1fr]"><div className="border border-[#cfdfda] bg-white p-4"><div className="flex items-start justify-between gap-3"><div><p className="eyebrow">EDIÇÃO COMPLETA</p><h4 className="font-display mt-1 text-base font-bold text-[#173d4a]">{editing ? `Editar questão #${editing.id}` : "Nova questão"}</h4></div>{editing && <button onClick={() => setEditing(null)} className="text-[11px] font-bold text-[#895a22]">Cancelar edição</button>}</div><QuestionForm key={editing?.id ?? newQuestionFormKey(newQuestionRevision)} question={editing} contents={contents} contentsLoading={contentsLoading} pending={pending} onSubmit={async data => { if (editing) await onUpdate(editing.id, data); else { await onCreate(data); setNewQuestionRevision(value => value + 1); } setEditing(null); }}/></div><div><div className="flex flex-col gap-2 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-[#6e8589]"/><Input value={search} onChange={event => onSearch(event.target.value)} placeholder="Pesquisar enunciado" className="h-10 bg-white pl-9 text-xs"/></label><select value={status} onChange={event => onStatus(event.target.value as KnowledgeStatus | "all")} className="h-10 border border-[#cec6b8] bg-white px-3 text-xs"><option value="all">Todos os status</option>{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><p className="mt-2 text-[10px] leading-4 text-[#687c7e]"><b>Todas as questões:</b> pesquise e filtre a lista; depois clique em <b>Editar questão</b> no cartão desejado. Para o ciclo editorial, use <b>Adicionar à revisão ROOT</b>; isso não é a fila privada do aluno.</p><div className="mt-3 max-h-[34rem] space-y-2 overflow-y-auto pr-1">{questionLoadState === "loading" ? <p className="border border-dashed border-[#b9d8cf] bg-[#f1f9f6] p-4 text-xs text-[#176a5a]">Carregando as questões da biblioteca central…</p> : questionLoadState === "empty" ? <p className="border border-dashed border-[#c7beb0] p-4 text-xs text-[#718084]">Nenhuma questão corresponde aos filtros. Altere a busca ou crie a primeira questão persistente ao lado.</p> : questions.map(question => <QuestionCard key={question.id} question={question} pending={pending} onEdit={() => setEditing(question)} onDelete={() => { onDelete(question.id); if (editing?.id === question.id) setEditing(null); }} onAddToReview={() => onAddToReview(question.id)}/>)}</div></div></div>;
}

function QuestionForm({ question, contents, contentsLoading, pending, onSubmit }: { question: Question | null; contents: Content[]; contentsLoading: boolean; pending: boolean; onSubmit: (data: any) => Promise<unknown> }) {
  const [form, setForm] = useState({ statement: question?.statement ?? "", questionType: question?.questionType ?? "certo_errado", optionsText: question?.options.join("\n") ?? "", answer: question?.answer ?? true, explanation: question?.explanation ?? "", difficulty: question?.difficulty ?? "intermediate", source: question?.source ?? "", banca: question?.banca ?? "", year: question?.year?.toString() ?? "", requiresReview: question?.requiresReview ?? false, status: question?.status ?? "draft", contentIds: question?.contentIds ?? [] as number[] });
  const [contentSearch, setContentSearch] = useState("");
  const [submitError, setSubmitError] = useState<string | null>(null);
  const options = normalizeQuestionOptions(form.optionsText);
  const visibleContents = useMemo(() => filterLinkOptions(contents, contentSearch, content => `${content.title} ${statusLabels[content.status]}`), [contents, contentSearch]);
  const updateForm = (updater: (value: typeof form) => typeof form) => {
    setForm(updater);
    if (submitError) setSubmitError(null);
  };
  const submit = async () => {
    const validationError = questionFormValidationError({ statement: form.statement, questionType: form.questionType, options, answer: form.answer });
    if (validationError) {
      setSubmitError(validationError);
      return;
    }
    setSubmitError(null);
    try {
      await onSubmit({ statement: form.statement, questionType: form.questionType, options, answer: form.answer, explanation: form.explanation || undefined, difficulty: form.difficulty, source: form.source || undefined, banca: form.banca || undefined, year: form.year ? Number(form.year) : null, requiresReview: form.requiresReview, status: form.status, contentIds: form.contentIds });
      if (!question) {
        setForm({ statement: "", questionType: "certo_errado", optionsText: "", answer: true, explanation: "", difficulty: "intermediate", source: "", banca: "", year: "", requiresReview: false, status: "draft", contentIds: [] });
        setContentSearch("");
      }
    } catch {
      // A mutação já apresenta a mensagem de erro específica no painel.
    }
  };
  return <div className="mt-4 space-y-3">
    <label className="block text-[11px] font-bold">Enunciado<Textarea value={form.statement} onChange={event => updateForm(value => ({ ...value, statement: event.target.value }))} className="mt-1 min-h-28 bg-white text-xs" placeholder="Escreva o enunciado da questão."/></label>
    <div className="grid gap-2 sm:grid-cols-2"><label className="text-[11px] font-bold">Tipo<select value={form.questionType} onChange={event => updateForm(value => ({ ...value, questionType: event.target.value as Question["questionType"], answer: event.target.value === "certo_errado" ? true : "" }))} className="mt-1 h-10 w-full border border-[#cec6b8] bg-white px-2 text-xs"><option value="certo_errado">Certo / Errado</option><option value="multipla_escolha">Múltipla escolha</option></select></label><label className="text-[11px] font-bold">Dificuldade<select value={form.difficulty} onChange={event => updateForm(value => ({ ...value, difficulty: event.target.value as Question["difficulty"] }))} className="mt-1 h-10 w-full border border-[#cec6b8] bg-white px-2 text-xs"><option value="basic">Básica</option><option value="intermediate">Intermediária</option><option value="advanced">Avançada</option></select></label></div>
    {form.questionType === "multipla_escolha" && <label className="block text-[11px] font-bold">Alternativas (uma por linha)<Textarea value={form.optionsText} onChange={event => updateForm(value => ({ ...value, optionsText: event.target.value }))} className="mt-1 min-h-24 bg-white text-xs" placeholder="A) Alternativa A\nB) Alternativa B\nC) Alternativa C"/></label>}
    <label className="block text-[11px] font-bold">Resposta correta{form.questionType === "certo_errado" ? <select value={String(form.answer)} onChange={event => updateForm(value => ({ ...value, answer: event.target.value === "true" }))} className="mt-1 h-10 w-full border border-[#cec6b8] bg-white px-2 text-xs"><option value="true">CERTO</option><option value="false">ERRADO</option></select> : <select value={typeof form.answer === "string" ? form.answer : ""} onChange={event => updateForm(value => ({ ...value, answer: event.target.value }))} className="mt-1 h-10 w-full border border-[#cec6b8] bg-white px-2 text-xs"><option value="">Selecione a alternativa</option>{options.map((option, index) => <option key={option} value={option}>{questionOptionLabel(option, index)}</option>)}</select>}<small className="mt-1 block font-normal text-[#718084]">O seletor mostra somente A/B/C/D; o texto completo permanece salvo na alternativa.</small></label>
    <label className="block text-[11px] font-bold">Comentário / fundamento<Textarea value={form.explanation} onChange={event => updateForm(value => ({ ...value, explanation: event.target.value }))} className="mt-1 min-h-20 bg-white text-xs" placeholder="Explique a resposta de forma didática."/></label>
    <div className="grid gap-2 sm:grid-cols-3"><Input value={form.banca} onChange={event => updateForm(value => ({ ...value, banca: event.target.value }))} placeholder="Banca" className="h-10 bg-white text-xs"/><Input value={form.year} onChange={event => updateForm(value => ({ ...value, year: event.target.value.replace(/\D/g, "").slice(0, 4) }))} placeholder="Ano" className="h-10 bg-white text-xs"/><Input value={form.source} onChange={event => updateForm(value => ({ ...value, source: event.target.value }))} placeholder="Fonte" className="h-10 bg-white text-xs"/></div>
    <div><p className="text-[11px] font-bold">Conteúdos vinculados (N:N)</p><p className="mt-1 text-[10px] leading-4 text-[#687c7e]">{contentsLoading ? "Carregando conteúdos existentes da biblioteca central…" : contents.length ? `${contents.length} conteúdo(s) disponíveis na biblioteca central. Pesquise e marque um ou mais para vinculá-los.` : "Não há conteúdos persistentes nesta biblioteca."}</p><Input value={contentSearch} onChange={event => setContentSearch(event.target.value)} placeholder="Pesquisar conteúdo para vincular" className="mt-1 h-9 bg-white text-xs"/><ToggleList values={form.contentIds} onChange={contentIds => updateForm(value => ({ ...value, contentIds }))} options={visibleContents.map(content => ({ id: content.id, label: content.title, caption: statusLabels[content.status] }))} empty={contentsLoading ? "Carregando conteúdos existentes da biblioteca central…" : contents.length ? "Nenhum conteúdo corresponde à busca." : "Não há conteúdos persistentes nesta biblioteca."}/></div>
    <div className="grid gap-2 sm:grid-cols-2"><label className="flex items-center gap-2 border border-[#d6d0c5] bg-[#fafaf7] p-2 text-[11px] font-bold"><input type="checkbox" checked={form.requiresReview} onChange={event => updateForm(value => ({ ...value, requiresReview: event.target.checked }))} className="accent-[#0e5a70]"/>Exigir revisão</label><label className="text-[11px] font-bold">Status<select value={form.status} onChange={event => updateForm(value => ({ ...value, status: event.target.value as KnowledgeStatus }))} className="mt-1 h-9 w-full border border-[#cec6b8] bg-white px-2 text-xs">{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label></div>
    {submitError && <p role="alert" className="border border-[#d8afa2] bg-[#fff0ec] p-3 text-xs font-semibold text-[#98462f]">{submitError}</p>}
    <button disabled={pending || form.statement.trim().length < 12} onClick={() => void submit()} className="flex w-full items-center justify-center gap-2 border border-[#87bbae] bg-[#0e5a70] px-3 py-2.5 text-xs font-bold text-white disabled:opacity-50"><FilePenLine className="h-4 w-4"/>{question ? "Salvar edição e registrar histórico" : "Criar questão"}</button>
    {question && <QuestionHistory questionId={question.id}/>}</div>;
}

function QuestionCard({ question, pending, onEdit, onDelete, onAddToReview }: { question: Question; pending: boolean; onEdit: () => void; onDelete: () => void; onAddToReview: () => void }) {
  const [confirmingDeletion, setConfirmingDeletion] = useState(false);
  return <article className="border border-[#d3ded9] bg-white p-3"><div className="flex items-start justify-between gap-2"><p className="line-clamp-2 text-xs font-bold leading-5 text-[#1d4652]">#{question.id} · {question.statement}</p><StatusBadge status={question.status}/></div><p className="mt-2 text-[10px] text-[#718084]">{question.questionType === "certo_errado" ? "CERTO / ERRADO" : "MÚLTIPLA ESCOLHA"} · {question.banca ?? "Sem banca"}{question.year ? ` · ${question.year}` : ""}</p><div className="mt-2 flex flex-wrap gap-1">{question.contents.length ? question.contents.map(content => <span key={content.id} className="border border-[#c7dcd5] bg-[#f1f9f6] px-1.5 py-0.5 text-[9px] text-[#216459]">{content.title}</span>) : <span className="text-[10px] text-[#8a7770]">Sem conteúdo vinculado</span>}</div>{confirmingDeletion ? <div className="mt-3 border border-[#d8afa2] bg-[#fff0ec] p-2"><p className="text-[10px] leading-4 text-[#98462f]">Excluir esta questão definitivamente? Itens já usados em simulados são protegidos e devem ser inativados.</p><div className="mt-2 flex gap-3"><button disabled={pending} onClick={onDelete} className="text-[10px] font-bold text-[#98462f] hover:underline">Confirmar exclusão</button><button disabled={pending} onClick={() => setConfirmingDeletion(false)} className="text-[10px] font-bold text-[#5f706f] hover:underline">Cancelar</button></div></div> : <div className="mt-3 flex flex-wrap gap-3"><button disabled={pending} onClick={onEdit} className="text-[10px] font-bold text-[#0e5a70] hover:underline">Editar questão</button><button disabled={pending || question.status === "review"} onClick={onAddToReview} className="inline-flex items-center gap-1 text-[10px] font-bold text-[#8d611a] hover:underline"><Send className="h-3 w-3"/>Adicionar à revisão ROOT</button><button disabled={pending} onClick={() => setConfirmingDeletion(true)} className="text-[10px] font-bold text-[#98462f] hover:underline">Excluir</button></div>}</article>;
}

function QuestionsByContent({ contents, questions, loading, pending, onOpenQuestion }: { contents: Content[]; questions: Question[]; loading: boolean; pending: boolean; onOpenQuestion: (id: number) => void }) {
  const [search, setSearch] = useState("");
  const [showEmpty, setShowEmpty] = useState(false);
  const [expandedContentIds, setExpandedContentIds] = useState<Set<number>>(() => new Set());
  const allGroups = useMemo(() => contents
    .filter(content => `${content.title} ${content.description ?? ""}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase()))
    .map(content => ({ content, questions: questions.filter(question => question.contentIds.includes(content.id)) })), [contents, questions, search]);
  const questionCountsByContent = useMemo(() => countQuestionsByContent(questions), [questions]);
  const groupsWithQuestions = allGroups.filter(group => (questionCountsByContent.get(group.content.id) ?? 0) > 0);
  const groups = showEmpty ? allGroups : groupsWithQuestions;
  const toggleExpanded = (contentId: number, isOpen: boolean) => setExpandedContentIds(current => {
    const next = new Set(current);
    if (isOpen) next.add(contentId); else next.delete(contentId);
    return next;
  });
  if (loading) return <div className="mt-5 border border-dashed border-[#b9d8cf] bg-[#f1f9f6] p-4 text-xs text-[#176a5a]">Carregando conteúdos e todas as questões vinculadas da biblioteca central…</div>;
  return <div className="mt-5"><div className="border border-[#c7ded6] bg-white p-3 text-[11px] leading-5 text-[#45696c]"><b className="text-[#173d4a]">Questões do simulado por conteúdo:</b> há <b className="text-[#176a5a]">{questions.length} questão(ões) na biblioteca</b>, distribuídas em <b className="text-[#176a5a]">{groupsWithQuestions.length} conteúdo(s)</b>. A lista começa pelos conteúdos que já possuem questões, para que todas possam ser conferidas e editadas sem ficarem escondidas entre grupos vazios.</div><div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={() => setExpandedContentIds(new Set(groups.map(group => group.content.id)))} className="border border-[#b9d8cf] bg-[#f1f9f6] px-2.5 py-1.5 text-[10px] font-bold text-[#176a5a]">Expandir todas as questões visíveis</button><button type="button" onClick={() => setExpandedContentIds(new Set())} className="border border-[#c9d8d5] bg-white px-2.5 py-1.5 text-[10px] font-bold text-[#45696c]">Recolher grupos</button><button type="button" onClick={() => setShowEmpty(current => !current)} className="border border-[#c9d8d5] bg-white px-2.5 py-1.5 text-[10px] font-bold text-[#45696c]">{showEmpty ? "Ocultar conteúdos sem questões" : `Exibir também ${Math.max(0, allGroups.length - groupsWithQuestions.length)} conteúdo(s) sem questões`}</button></div><label className="relative mt-3 block"><Search className="absolute left-3 top-3 h-4 w-4 text-[#6e8589]"/><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="Pesquisar conteúdo para localizar todas as suas questões" className="h-10 bg-white pl-9 text-xs"/></label><div className="mt-3 max-h-[38rem] space-y-2 overflow-y-auto pr-1">{groups.length === 0 ? <p className="border border-dashed border-[#c7beb0] bg-white p-4 text-xs text-[#718084]">Nenhum conteúdo com questões corresponde à busca. Você pode optar por exibir também os conteúdos ainda vazios.</p> : groups.map(({ content, questions: linkedQuestions }) => <details key={content.id} className="border border-[#d3ded9] bg-white" open={expandedContentIds.has(content.id)} onToggle={event => toggleExpanded(content.id, event.currentTarget.open)}><summary className="flex cursor-pointer list-none items-center justify-between gap-3 p-3"><span><b className="text-xs text-[#1d4652]">#{content.id} · {content.title}</b><small className="mt-1 block text-[10px] text-[#718084]">{content.disciplineIds.length} disciplina(s) vinculada(s)</small></span><span className="border border-[#c7dcd5] bg-[#f1f9f6] px-2 py-1 text-[10px] font-bold text-[#216459]">{linkedQuestions.length} questão(ões)</span></summary><div className="border-t border-[#e1e8e4] p-3">{linkedQuestions.length === 0 ? <p className="text-[11px] text-[#718084]">Ainda não há questões vinculadas a este conteúdo. Crie uma questão e marque este conteúdo no vínculo N:N.</p> : <div className="space-y-2">{linkedQuestions.map(question => <article key={question.id} className="border border-[#e1e8e4] bg-[#fbfdfc] p-2"><p className="line-clamp-2 text-[11px] font-semibold leading-5 text-[#1d4652]">#{question.id} · {question.statement}</p><div className="mt-2 flex items-center justify-between gap-2"><StatusBadge status={question.status}/><button disabled={pending} onClick={() => onOpenQuestion(question.id)} className="text-[10px] font-bold text-[#0e5a70] hover:underline">Editar questão</button></div></article>)}</div>}</div></details>)}</div></div>;
}

function ContentWorkspace({ disciplines, contents, contentsLoading, pending, onCreate, onUpdate, onUploadImage, onSend }: { disciplines: Discipline[]; contents: Content[]; contentsLoading: boolean; pending: boolean; onCreate: (data: any) => void; onUpdate: (id: number, data: any) => void; onUploadImage: (data: { fileName: string; mimeType: "image/jpeg" | "image/png" | "image/webp"; base64: string }) => Promise<{ url: string }>; onSend: (id: number) => void }) {
  const [editing, setEditing] = useState<any>(null);
  const [search, setSearch] = useState("");
  const visibleContents = useMemo(() => filterLinkOptions(contents, search, content => `${content.title} ${content.description ?? ""}`), [contents, search]);
  const contentLoadState = libraryLoadState(contentsLoading, contents.length);
  return <div className="mt-5 grid gap-5 xl:grid-cols-[.95fr_1.05fr]"><div className="border border-[#cfdfda] bg-white p-4"><div className="flex items-start justify-between"><div><p className="eyebrow">CONTEÚDO DIDÁTICO</p><h4 className="font-display mt-1 text-base font-bold text-[#173d4a]">{editing ? `Editar conteúdo #${editing.id}` : "Novo conteúdo"}</h4></div>{editing && <button onClick={() => setEditing(null)} className="text-[11px] font-bold text-[#895a22]">Cancelar</button>}</div><ContentFormWithImage key={editing?.id ?? "new-content"} content={editing} disciplines={disciplines} pending={pending} onUploadImage={onUploadImage} onSubmit={data => { if (editing) onUpdate(editing.id, data); else onCreate(data); setEditing(null); }}/></div><div><label className="relative block"><Search className="absolute left-3 top-3 h-4 w-4 text-[#6e8589]"/><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="Procurar conteúdo existente para editar" className="h-10 bg-white pl-9 text-xs"/></label><p className="mt-2 text-[10px] leading-4 text-[#687c7e]">{contentsLoading ? "Carregando a biblioteca central…" : contents.length ? `${contents.length} conteúdo(s) disponíveis. Use a busca e clique em Editar no conteúdo desejado.` : "Não há conteúdos persistentes nesta biblioteca."}</p><div className="mt-3 max-h-[33rem] space-y-2 overflow-y-auto pr-1">{contentLoadState === "loading" ? <p className="border border-dashed border-[#b9d8cf] bg-[#f1f9f6] p-4 text-xs text-[#176a5a]">Carregando conteúdos da biblioteca central…</p> : contentLoadState === "empty" ? <p className="border border-dashed border-[#c7beb0] p-4 text-xs text-[#718084]">Não há conteúdos persistentes nesta biblioteca.</p> : visibleContents.length === 0 ? <p className="border border-dashed border-[#c7beb0] p-4 text-xs text-[#718084]">Nenhum conteúdo corresponde à busca.</p> : visibleContents.map(content => <ContentEditorCard key={content.id} content={content} pending={pending} onEdit={() => setEditing(content)} onSend={() => onSend(content.id)}/>)}</div></div></div>;
  return <div className="mt-5 grid gap-5 xl:grid-cols-[.95fr_1.05fr]"><div className="border border-[#cfdfda] bg-white p-4"><div className="flex items-start justify-between"><div><p className="eyebrow">CONTEÚDO DIDÁTICO</p><h4 className="font-display mt-1 text-base font-bold text-[#173d4a]">{editing ? `Editar conteúdo #${editing.id}` : "Novo conteúdo"}</h4></div>{editing && <button onClick={() => setEditing(null)} className="text-[11px] font-bold text-[#895a22]">Cancelar</button>}</div><ContentForm key={editing?.id ?? "new-content"} content={editing} disciplines={disciplines} pending={pending} onSubmit={data => { if (editing) onUpdate(editing.id, data); else onCreate(data); setEditing(null); }}/></div><div><label className="relative block"><Search className="absolute left-3 top-3 h-4 w-4 text-[#6e8589]"/><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="Procurar conteúdo existente para editar" className="h-10 bg-white pl-9 text-xs"/></label><p className="mt-2 text-[10px] leading-4 text-[#687c7e]">{contents.length ? `${contents.length} conteúdo(s) disponíveis. Use a busca e clique em Editar no conteúdo desejado.` : "Carregando a biblioteca central..."}</p><div className="mt-3 max-h-[33rem] space-y-2 overflow-y-auto pr-1">{contents.length === 0 ? <p className="border border-dashed border-[#c7beb0] p-4 text-xs text-[#718084]">Nenhum conteúdo persistente foi carregado. Atualize a página para consultar a biblioteca padrão.</p> : visibleContents.length === 0 ? <p className="border border-dashed border-[#c7beb0] p-4 text-xs text-[#718084]">Nenhum conteúdo corresponde à busca.</p> : visibleContents.map(content => <article key={content.id} className="border border-[#d3ded9] bg-white p-3"><div className="flex items-start justify-between gap-2"><div><p className="text-xs font-bold text-[#1d4652]">#{content.id} · {content.title}</p><p className="mt-1 line-clamp-2 text-[11px] text-[#718084]">{content.cardText || content.description || "Sem resumo."}</p></div><StatusBadge status={content.status}/></div>{content.objective && <p className="mt-2 text-[10px] leading-4 text-[#45696c]"><b>Objetivo:</b> {content.objective}</p>}<p className="mt-2 text-[10px] text-[#718084]">{content.disciplineIds.length ? `${content.disciplineIds.length} disciplina(s) vinculada(s)` : "Ainda sem disciplina vinculada"}</p>{(content.videoUrl || content.materialUrl) && <div className="mt-2 flex flex-wrap gap-2">{content.videoUrl && <a href={content.videoUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 border border-[#b9d8cf] bg-[#f1f9f6] px-2 py-1 text-[10px] font-bold text-[#176a5a]"><Link2 className="h-3 w-3"/>{content.videoLabel || "Vídeo complementar"}</a>}{content.materialUrl && <a href={content.materialUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 border border-[#c8d6e2] bg-[#f3f8fc] px-2 py-1 text-[10px] font-bold text-[#225d7e]"><Link2 className="h-3 w-3"/>{content.materialLabel || "Material complementar"}</a>}</div>}<div className="mt-3 flex gap-3"><button disabled={pending} onClick={() => setEditing(content)} className="text-[10px] font-bold text-[#0e5a70] hover:underline">Editar</button><button disabled={pending || content.status === "review"} onClick={() => onSend(content.id)} className="inline-flex items-center gap-1 text-[10px] font-bold text-[#8d611a] hover:underline"><Send className="h-3 w-3"/>Enviar para revisão</button><ContentHistory contentId={content.id}/></div></article>)}</div></div></div>;
}

function ContentEditorCard({ content, pending, onEdit, onSend }: { content: Content; pending: boolean; onEdit: () => void; onSend: () => void }) {
  return <article className="overflow-hidden border border-[#d3ded9] bg-white"><div className="flex gap-3 p-3">{content.coverImageUrl ? <img src={content.coverImageUrl} alt="" className="h-20 w-24 shrink-0 object-cover"/> : <div className="flex h-20 w-24 shrink-0 items-center justify-center bg-[#edf5f2] text-[#62908a]"><ImagePlus className="h-5 w-5"/></div>}<div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><p className="text-[10px] font-bold tracking-wider text-[#176a5a]">CONTEÚDO #{content.id}</p><p className="mt-0.5 text-xs font-bold text-[#1d4652]">{content.title}</p></div><StatusBadge status={content.status}/></div><p className="mt-1 line-clamp-2 text-[11px] leading-4 text-[#718084]">{content.cardText || content.description || "Sem texto de card."}</p></div></div><div className="border-t border-[#e1e8e4] px-3 py-2"><div className="grid gap-2 sm:grid-cols-2">{content.objective && <p className="text-[10px] leading-4 text-[#45696c]"><b>Objetivo:</b> {content.objective}</p>}{content.description && <p className="text-[10px] leading-4 text-[#718084]"><b>Resumo:</b> {content.description}</p>}</div>{content.body && <p className="mt-2 line-clamp-2 text-[10px] leading-4 text-[#687c7e]"><b>Texto do conteúdo:</b> {content.body}</p>}<p className="mt-2 text-[10px] text-[#718084]">{content.disciplineIds.length ? `${content.disciplineIds.length} disciplina(s) vinculada(s)` : "Ainda sem disciplina vinculada"}</p>{(content.videoUrl || content.materialUrl) && <div className="mt-2 flex flex-wrap gap-2">{content.videoUrl && <a href={content.videoUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 border border-[#b9d8cf] bg-[#f1f9f6] px-2 py-1 text-[10px] font-bold text-[#176a5a]"><Link2 className="h-3 w-3"/>{content.videoLabel || "Vídeo complementar"}</a>}{content.materialUrl && <a href={content.materialUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 border border-[#c8d6e2] bg-[#f3f8fc] px-2 py-1 text-[10px] font-bold text-[#225d7e]"><Link2 className="h-3 w-3"/>{content.materialLabel || "Material complementar"}</a>}</div>}<div className="mt-3 flex gap-3"><button disabled={pending} onClick={onEdit} className="text-[10px] font-bold text-[#0e5a70] hover:underline">Editar</button><button disabled={pending || content.status === "review"} onClick={onSend} className="inline-flex items-center gap-1 text-[10px] font-bold text-[#8d611a] hover:underline"><Send className="h-3 w-3"/>Enviar para revisão</button><ContentHistory contentId={content.id}/></div></div></article>;
}

function ContentFormWithImage({ content, disciplines, pending, onUploadImage, onSubmit }: { content: Content | null; disciplines: Discipline[]; pending: boolean; onUploadImage: (data: { fileName: string; mimeType: "image/jpeg" | "image/png" | "image/webp"; base64: string }) => Promise<{ url: string }>; onSubmit: (data: any) => void }) {
  const [form, setForm] = useState({ title: content?.title ?? "", objective: content?.objective ?? "", description: content?.description ?? "", cardText: content?.cardText ?? "", body: content?.body ?? "", coverImageUrl: content?.coverImageUrl ?? "", videoUrl: content?.videoUrl ?? "", videoLabel: content?.videoLabel ?? "", materialUrl: content?.materialUrl ?? "", materialLabel: content?.materialLabel ?? "", noticeKind: content?.noticeKind ?? null as ContentNoticeKind | null, requiresReview: content?.requiresReview ?? false, status: content?.status ?? "draft", disciplineIds: content?.disciplineIds ?? [] as number[] });
  const [disciplineSearch, setDisciplineSearch] = useState("");
  const [imageMessage, setImageMessage] = useState("");
  const visibleDisciplines = useMemo(() => filterLinkOptions(disciplines, disciplineSearch, discipline => `${discipline.name} ${discipline.shortName}`), [disciplines, disciplineSearch]);
  const selectImage = async (file?: File) => {
    if (!file) return;
    if (!(["image/jpeg", "image/png", "image/webp"] as string[]).includes(file.type) || file.size > 4 * 1024 * 1024) { setImageMessage("Selecione JPG, PNG ou WEBP com até 4 MB."); return; }
    try { setImageMessage("Enviando imagem…"); const url = await onUploadImage({ fileName: file.name, mimeType: file.type as "image/jpeg" | "image/png" | "image/webp", base64: await readContentImageAsBase64(file) }); setForm(value => ({ ...value, coverImageUrl: url.url })); setImageMessage("Imagem pronta para salvar no card."); } catch { setImageMessage("Não foi possível enviar a imagem. Tente novamente."); }
  };
  return <div className="mt-4 space-y-3">
    <Input value={form.title} onChange={event => setForm(value => ({ ...value, title: event.target.value }))} placeholder="Título do conteúdo" className="h-10 bg-white text-xs"/>
    <Textarea value={form.objective} onChange={event => setForm(value => ({ ...value, objective: event.target.value }))} placeholder="Objetivo de aprendizagem" className="min-h-16 bg-white text-xs"/>
    <Textarea value={form.description} onChange={event => setForm(value => ({ ...value, description: event.target.value }))} placeholder="Resumo pedagógico" className="min-h-20 bg-white text-xs"/>
    <Textarea value={form.cardText} onChange={event => setForm(value => ({ ...value, cardText: event.target.value }))} placeholder="Texto curto do card (exibido na vitrine)" className="min-h-16 bg-white text-xs"/>
    <label className="block border border-dashed border-[#b9d8cf] bg-[#f7fbf9] p-3 text-[11px] font-bold text-[#1d4652]">Imagem opcional do card<input type="file" accept="image/jpeg,image/png,image/webp" className="mt-2 block w-full text-[10px] font-normal" onChange={event => void selectImage(event.target.files?.[0])}/><span className="mt-1 block font-normal text-[#687c7e]">JPG, PNG ou WEBP, até 4 MB. A imagem mantém o recorte proporcional do card.</span>{imageMessage && <span className="mt-1 block font-normal text-[#176a5a]">{imageMessage}</span>}{form.coverImageUrl && <div className="mt-2 flex items-center gap-2"><img src={form.coverImageUrl} alt="Prévia da imagem do conteúdo" className="h-16 w-20 object-cover"/><button type="button" onClick={() => setForm(value => ({ ...value, coverImageUrl: "" }))} className="text-[10px] font-bold text-[#895a22] hover:underline">Remover imagem</button></div>}</label>
    <ContentBodyEditor value={form.body} onChange={body => setForm(value => ({ ...value, body }))}/>
    <div className="grid gap-2 sm:grid-cols-2"><Input value={form.videoLabel} onChange={event => setForm(value => ({ ...value, videoLabel: event.target.value }))} placeholder="Rótulo do vídeo" className="h-10 bg-white text-xs"/><Input value={form.videoUrl} onChange={event => setForm(value => ({ ...value, videoUrl: event.target.value }))} placeholder="https://… vídeo complementar" className="h-10 bg-white text-xs"/><Input value={form.materialLabel} onChange={event => setForm(value => ({ ...value, materialLabel: event.target.value }))} placeholder="Rótulo do material" className="h-10 bg-white text-xs"/><Input value={form.materialUrl} onChange={event => setForm(value => ({ ...value, materialUrl: event.target.value }))} placeholder="https://… material complementar" className="h-10 bg-white text-xs"/></div>
    <label className="block text-[11px] font-bold">Disciplinas já existentes para vincular (N:N)<Input value={disciplineSearch} onChange={event => setDisciplineSearch(event.target.value)} placeholder="Pesquisar disciplina existente" className="mt-1 h-9 bg-white text-xs"/><ToggleList values={form.disciplineIds} onChange={disciplineIds => setForm(value => ({ ...value, disciplineIds }))} options={visibleDisciplines.map(discipline => ({ id: discipline.id, label: discipline.name, caption: discipline.shortName }))} empty={disciplines.length ? "Nenhuma disciplina corresponde à busca." : "Cadastre uma disciplina antes de vinculá-la."}/></label>
    <ContentNoticeControl value={form.noticeKind} onChange={noticeKind => setForm(value => ({ ...value, noticeKind }))}/>
    <div className="grid gap-2 sm:grid-cols-2"><label className="flex items-center gap-2 border border-[#d6d0c5] bg-[#fafaf7] p-2 text-[11px] font-bold"><input type="checkbox" checked={form.requiresReview} onChange={event => setForm(value => ({ ...value, requiresReview: event.target.checked }))} className="accent-[#0e5a70]"/>Exigir revisão</label><select value={form.status} onChange={event => setForm(value => ({ ...value, status: event.target.value as KnowledgeStatus }))} className="h-10 border border-[#cec6b8] bg-white px-2 text-xs">{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div>
    <p className="text-[10px] leading-4 text-[#687c7e]">Use os botões no texto completo para criar destaques e fórmulas. O conteúdo continua aceitando texto comum, imagens, resumo e links.</p>
    <button disabled={pending || form.title.trim().length < 4} onClick={() => onSubmit({ ...form })} className="flex w-full items-center justify-center gap-2 border border-[#87bbae] bg-[#0e5a70] px-3 py-2.5 text-xs font-bold text-white disabled:opacity-50"><PlusCircle className="h-4 w-4"/>{content ? "Salvar conteúdo" : "Criar conteúdo"}</button>
  </div>;
}

function ContentForm({ content, disciplines, pending, onSubmit }: { content: Content | null; disciplines: Discipline[]; pending: boolean; onSubmit: (data: any) => void }) {
  const [form, setForm] = useState({ title: content?.title ?? "", objective: content?.objective ?? "", description: content?.description ?? "", cardText: content?.cardText ?? "", body: content?.body ?? "", videoUrl: content?.videoUrl ?? "", videoLabel: content?.videoLabel ?? "", materialUrl: content?.materialUrl ?? "", materialLabel: content?.materialLabel ?? "", requiresReview: content?.requiresReview ?? false, status: content?.status ?? "draft", disciplineIds: content?.disciplineIds ?? [] as number[] });
  const [disciplineSearch, setDisciplineSearch] = useState("");
  const visibleDisciplines = useMemo(() => filterLinkOptions(disciplines, disciplineSearch, discipline => `${discipline.name} ${discipline.shortName}`), [disciplines, disciplineSearch]);
  return <div className="mt-4 space-y-3"><Input value={form.title} onChange={event => setForm(value => ({ ...value, title: event.target.value }))} placeholder="Título do conteúdo" className="h-10 bg-white text-xs"/><Textarea value={form.objective} onChange={event => setForm(value => ({ ...value, objective: event.target.value }))} placeholder="Objetivo de aprendizagem" className="min-h-16 bg-white text-xs"/><Textarea value={form.description} onChange={event => setForm(value => ({ ...value, description: event.target.value }))} placeholder="Resumo pedagógico" className="min-h-20 bg-white text-xs"/><Textarea value={form.cardText} onChange={event => setForm(value => ({ ...value, cardText: event.target.value }))} placeholder="Texto curto do card (exibido na vitrine)" className="min-h-16 bg-white text-xs"/><Textarea value={form.body} onChange={event => setForm(value => ({ ...value, body: event.target.value }))} placeholder="Texto autoral do conteúdo (opcional)" className="min-h-32 bg-white text-xs"/><div className="grid gap-2 sm:grid-cols-2"><Input value={form.videoLabel} onChange={event => setForm(value => ({ ...value, videoLabel: event.target.value }))} placeholder="Rótulo do vídeo" className="h-10 bg-white text-xs"/><Input value={form.videoUrl} onChange={event => setForm(value => ({ ...value, videoUrl: event.target.value }))} placeholder="https://… vídeo complementar" className="h-10 bg-white text-xs"/><Input value={form.materialLabel} onChange={event => setForm(value => ({ ...value, materialLabel: event.target.value }))} placeholder="Rótulo do material" className="h-10 bg-white text-xs"/><Input value={form.materialUrl} onChange={event => setForm(value => ({ ...value, materialUrl: event.target.value }))} placeholder="https://… material complementar" className="h-10 bg-white text-xs"/></div><label className="block text-[11px] font-bold">Disciplinas já existentes para vincular (N:N)<Input value={disciplineSearch} onChange={event => setDisciplineSearch(event.target.value)} placeholder="Pesquisar disciplina existente" className="mt-1 h-9 bg-white text-xs"/><ToggleList values={form.disciplineIds} onChange={disciplineIds => setForm(value => ({ ...value, disciplineIds }))} options={visibleDisciplines.map(discipline => ({ id: discipline.id, label: discipline.name, caption: discipline.shortName }))} empty={disciplines.length ? "Nenhuma disciplina corresponde à busca." : "Cadastre uma disciplina antes de vinculá-la."}/></label><div className="grid gap-2 sm:grid-cols-2"><label className="flex items-center gap-2 border border-[#d6d0c5] bg-[#fafaf7] p-2 text-[11px] font-bold"><input type="checkbox" checked={form.requiresReview} onChange={event => setForm(value => ({ ...value, requiresReview: event.target.checked }))} className="accent-[#0e5a70]"/>Exigir revisão</label><select value={form.status} onChange={event => setForm(value => ({ ...value, status: event.target.value as KnowledgeStatus }))} className="h-10 border border-[#cec6b8] bg-white px-2 text-xs">{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><p className="text-[10px] leading-4 text-[#687c7e]">Os links aparecem no card quando preenchidos. Escolha <b>EM REVISÃO</b> para enviar este conteúdo automaticamente à fila.</p><button disabled={pending || form.title.trim().length < 4} onClick={() => onSubmit({ ...form })} className="flex w-full items-center justify-center gap-2 border border-[#87bbae] bg-[#0e5a70] px-3 py-2.5 text-xs font-bold text-white disabled:opacity-50"><PlusCircle className="h-4 w-4"/>{content ? "Salvar conteúdo" : "Criar conteúdo"}</button></div>;
}

function DisciplineWorkspace({ courses, contents, disciplines, pending, onCreate, onUpdate }: { courses: Course[]; contents: Content[]; disciplines: Discipline[]; pending: boolean; onCreate: (data: any) => void; onUpdate: (id: number, data: any) => void }) {
  const [editing, setEditing] = useState<Discipline | null>(null);
  return <div className="mt-5 grid gap-5 xl:grid-cols-[.95fr_1.05fr]"><div className="border border-[#cfdfda] bg-white p-4"><div className="flex items-start justify-between"><div><p className="eyebrow">MATRIZ REUTILIZÁVEL</p><h4 className="font-display mt-1 text-base font-bold text-[#173d4a]">{editing ? `Editar ${editing.shortName}` : "Nova disciplina"}</h4></div>{editing && <button onClick={() => setEditing(null)} className="text-[11px] font-bold text-[#895a22]">Cancelar</button>}</div><DisciplineForm key={editing?.id ?? "new-discipline"} discipline={editing} courses={courses} contents={contents} pending={pending} onSubmit={data => { if (editing) onUpdate(editing.id, data); else onCreate(data); setEditing(null); }}/></div><div className="max-h-[38rem] space-y-2 overflow-y-auto pr-1">{disciplines.length === 0 ? <p className="border border-dashed border-[#c7beb0] p-4 text-xs text-[#718084]">Ainda não há disciplinas persistentes. Você pode montar uma matriz uma única vez e vinculá-la a vários cursos.</p> : disciplines.map(discipline => <article key={discipline.id} className="border border-[#d3ded9] bg-white p-3"><div className="flex items-start justify-between"><div><p className="text-xs font-bold text-[#1d4652]">{discipline.name} <span className="text-[#638286]">({discipline.shortName})</span></p><p className="mt-1 text-[10px] text-[#718084]">{discipline.courseIds.length} curso(s) · {discipline.contentIds.length} conteúdo(s)</p></div><StatusBadge status={discipline.status}/></div><button disabled={pending} onClick={() => setEditing(discipline)} className="mt-3 text-[10px] font-bold text-[#0e5a70] hover:underline">Editar vínculos</button></article>)}</div></div>;
}

function DisciplineForm({ discipline, courses, contents, pending, onSubmit }: { discipline: Discipline | null; courses: Course[]; contents: Content[]; pending: boolean; onSubmit: (data: any) => void }) {
  const [form, setForm] = useState({ name: discipline?.name ?? "", shortName: discipline?.shortName ?? "", description: discipline?.description ?? "", requiresReview: discipline?.requiresReview ?? false, status: discipline?.status ?? "draft", courseIds: discipline?.courseIds ?? [] as string[], contentIds: discipline?.contentIds ?? [] as number[] });
  return <div className="mt-4 space-y-3"><div className="grid gap-2 sm:grid-cols-[1fr_.4fr]"><Input value={form.name} onChange={event => setForm(value => ({ ...value, name: event.target.value }))} placeholder="Nome da disciplina" className="h-10 bg-white text-xs"/><Input value={form.shortName} onChange={event => setForm(value => ({ ...value, shortName: event.target.value.toUpperCase() }))} placeholder="Sigla" className="h-10 bg-white text-xs"/></div><Textarea value={form.description} onChange={event => setForm(value => ({ ...value, description: event.target.value }))} placeholder="Descrição da disciplina" className="min-h-20 bg-white text-xs"/><label className="block text-[11px] font-bold">Cursos vinculados<ToggleList values={form.courseIds} onChange={courseIds => setForm(value => ({ ...value, courseIds }))} options={courses.map(course => ({ id: course.id, label: course.title, caption: course.track }))} empty="Nenhum curso cadastrado ainda."/></label><label className="block text-[11px] font-bold">Conteúdos vinculados<ToggleList values={form.contentIds} onChange={contentIds => setForm(value => ({ ...value, contentIds }))} options={contents.map(content => ({ id: content.id, label: content.title, caption: statusLabels[content.status] }))} empty="Nenhum conteúdo cadastrado ainda."/></label><div className="grid gap-2 sm:grid-cols-2"><label className="flex items-center gap-2 border border-[#d6d0c5] bg-[#fafaf7] p-2 text-[11px] font-bold"><input type="checkbox" checked={form.requiresReview} onChange={event => setForm(value => ({ ...value, requiresReview: event.target.checked }))} className="accent-[#0e5a70]"/>Exigir revisão</label><select value={form.status} onChange={event => setForm(value => ({ ...value, status: event.target.value as KnowledgeStatus }))} className="h-10 border border-[#cec6b8] bg-white px-2 text-xs">{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><button disabled={pending || form.name.trim().length < 3 || form.shortName.trim().length < 2} onClick={() => onSubmit(form)} className="flex w-full items-center justify-center gap-2 border border-[#87bbae] bg-[#0e5a70] px-3 py-2.5 text-xs font-bold text-white disabled:opacity-50"><PlusCircle className="h-4 w-4"/>{discipline ? "Salvar disciplina" : "Criar disciplina"}</button></div>;
}

function ReviewWorkspace({ reviews, search, type, status, pending, onSearch, onType, onStatus, onOpenQuestion, onDecide }: { reviews: ReviewItem[]; search: string; type: "all" | "question" | "content"; status: "all" | ReviewItem["status"]; pending: boolean; onSearch: (value: string) => void; onType: (value: "all" | "question" | "content") => void; onStatus: (value: "all" | ReviewItem["status"]) => void; onOpenQuestion: (id: number) => void; onDecide: (id: number, decision: "approved" | "rejected" | "correction_requested", notes?: string) => void }) {
  const [notesByReview, setNotesByReview] = useState<Record<number, string>>({});
  const hasActiveFilters = Boolean(search.trim()) || type !== "all" || status !== "pending";
  const emptyStateMessage = reviewEmptyStateMessage(hasActiveFilters);

  return <div className="mt-5">
    <aside className="border border-[#c7ded6] bg-white p-3 text-[11px] leading-5 text-[#45696c]"><b className="text-[#173d4a]">Fluxo de revisão:</b><ol className="mt-1 list-decimal space-y-0.5 pl-4">{reviewFlowSteps.map(step => <li key={step}>{step}</li>)}</ol><p className="mt-2">No banco de questões, use <b>Adicionar à revisão</b>. Aqui, abra a questão, registre uma correção quando necessário e finalize a decisão. <b>Correção</b> e <b>Rejeitar</b> exigem justificativa.</p></aside>
    <div className="mt-3 grid gap-2 md:grid-cols-[1fr_.55fr_.7fr]">
      <label className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-[#6e8589]"/><Input value={search} onChange={event => onSearch(event.target.value)} placeholder="Pesquisar item" className="h-10 bg-white pl-9 text-xs"/></label>
      <select value={type} onChange={event => onType(event.target.value as "all" | "question" | "content")} className="h-10 border border-[#cec6b8] bg-white px-2 text-xs"><option value="all">Todos os tipos</option><option value="question">Questões</option><option value="content">Conteúdos</option></select>
      <select value={status} onChange={event => onStatus(event.target.value as "all" | ReviewItem["status"])} className="h-10 border border-[#cec6b8] bg-white px-2 text-xs"><option value="all">Todas as decisões</option>{Object.entries(reviewLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select>
    </div>
    <div className="mt-4 space-y-2">
      {reviews.length === 0 ? <p className="border border-dashed border-[#c7beb0] bg-white p-4 text-xs leading-5 text-[#718084]">{emptyStateMessage}</p> : reviews.map(review => <article key={review.id} className="border border-[#d3ded9] bg-white p-3"><div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-[10px] font-bold tracking-wider text-[#176a5a]">{review.itemType === "question" ? "QUESTÃO" : "CONTEÚDO"} #{review.itemId} · {reviewLabels[review.status]}</p><p className="mt-1 line-clamp-2 text-xs font-bold leading-5 text-[#1d4652]">{review.title}</p><p className="mt-1 text-[10px] text-[#718084]">Adicionada em: {new Date(review.createdAt).toLocaleString("pt-BR")} · Situação atual: {statusLabels[review.itemStatus]}</p>{review.notes && <p className="mt-2 border-l-2 border-[#b79b5d] pl-2 text-[10px] leading-4 text-[#765929]">Observação: {review.notes}</p>}{review.itemType === "question" && <button onClick={() => onOpenQuestion(review.itemId)} className="mt-2 text-[10px] font-bold text-[#0e5a70] hover:underline">Abrir e editar questão</button>}</div>{review.status === "pending" && <div className="min-w-56 space-y-2"><Textarea value={notesByReview[review.id] ?? ""} onChange={event => setNotesByReview(current => ({ ...current, [review.id]: event.target.value }))} placeholder="Obrigatório para correção ou rejeição" className="min-h-16 bg-white text-[10px]"/><div className="flex flex-wrap gap-2"><button disabled={pending} onClick={() => onDecide(review.id, "approved")} className="inline-flex items-center gap-1 border border-[#93cabb] bg-[#eff8f4] px-2 py-1.5 text-[10px] font-bold text-[#176a5a]"><CheckCircle2 className="h-3.5 w-3.5"/>Aprovar</button><button disabled={pending || (notesByReview[review.id]?.trim().length ?? 0) < 5} onClick={() => onDecide(review.id, "correction_requested", notesByReview[review.id])} className="inline-flex items-center gap-1 border border-[#d8bd7f] bg-[#fff8e8] px-2 py-1.5 text-[10px] font-bold text-[#8d611a]"><FilePenLine className="h-3.5 w-3.5"/>Correção</button><button disabled={pending || (notesByReview[review.id]?.trim().length ?? 0) < 5} onClick={() => onDecide(review.id, "rejected", notesByReview[review.id])} className="inline-flex items-center gap-1 border border-[#dcae9f] bg-[#fff0ec] px-2 py-1.5 text-[10px] font-bold text-[#98462f]"><XCircle className="h-3.5 w-3.5"/>Rejeitar</button></div></div>}</div></article>)}
    </div>
  </div>;
}

function QuestionHistory({ questionId }: { questionId: number }) {
  const query = trpc.admin.questions.changelog.useQuery({ id: questionId });
  return <details className="border-t border-[#e1dbd0] pt-3"><summary className="flex cursor-pointer items-center gap-1 text-[10px] font-bold text-[#436b70]"><History className="h-3.5 w-3.5"/>Histórico auditável da questão</summary><div className="mt-2 max-h-28 space-y-1 overflow-y-auto text-[10px] text-[#657b7e]">{query.isLoading ? "Carregando histórico…" : query.data?.length ? query.data.map(entry => <p key={entry.id}><b>{entry.changedField}</b>: {entry.oldValue ?? "—"} → {entry.newValue ?? "—"}</p>) : "Nenhuma alteração registrada além da criação."}</div></details>;
}

function ContentHistory({ contentId }: { contentId: number }) {
  const query = trpc.admin.contents.changelog.useQuery({ id: contentId });
  return <details className="text-[10px]"><summary className="inline-flex cursor-pointer items-center gap-1 font-bold text-[#436b70]"><History className="h-3 w-3"/>Histórico</summary><div className="mt-2 max-h-24 overflow-y-auto border border-[#dde5e0] bg-[#f9fbfa] p-2 text-[#657b7e]">{query.isLoading ? "Carregando…" : query.data?.length ? query.data.map(entry => <p key={entry.id}><b>{entry.changedField}</b>: {entry.oldValue ?? "—"} → {entry.newValue ?? "—"}</p>) : "Sem alterações."}</div></details>;
}
